def decrypt(t):
    stack = []
    for char in t:
        if not stack or stack[-1][0] != char:
            stack.append((char, 1))
        else:
            stack[-1] = (char, stack[-1][1] + 1)

    result = []
    while stack:
        char, count = stack.pop()
        result.extend([char] * count)

    return ''.join(result[::-1])

