def decrypt(t):
    s = []
    count = 1

    for i in range(1, len(t)):
        if t[i] == t[i - 1]:
            count += 1
        else:
            s.append(t[i - 1] * (count // (len(s) + 1)))
            count = 1

    s.append(t[-1] * (count // (len(s) + 1)))

    return ''.join(s)

